run PositiveSingleLine2Stations {
    some disj H1, H2 : Human | some disj M1 : Material | some disj C1 : Component {
        // Workstations form the line begin -> end
        Workstation = begin + end
        // Workers are either human or robots (no robots here)
        Worker = Human + Robot
        Human = H1 + H2
        Robot = none
        // Products: one component built from one material
        Material = M1
        Component = C1
        Product = M1 + C1
        Dangerous = none
        // Every workstation has workers, each worker works in exactly one workstation
        workers = begin->H1 + end->H2
        // The succ relation forms a single line from begin to end
        succ = begin->end
        // Components have parts, materials have no parts, no component is its own part
        parts = C1->M1
        // Every component is assembled in exactly one workstation
        workstation = C1->begin
    }
} for 2 Workstation, 2 Worker, 2 Product expect 1

run PositiveSingleLine3Stations {
    some disj H1, H2, H3 : Human | some disj M1 : Material | some disj C1 : Component | some disj W1 : Workstation - (begin + end) {
        Workstation = begin + end + W1
        Worker = Human + Robot
        Human = H1 + H2 + H3
        Robot = none
        Material = M1
        Component = C1
        Product = M1 + C1
        Dangerous = none
        // One human per workstation
        workers = begin->H1 + W1->H2 + end->H3
        // Single chain: begin -> W1 -> end
        succ = begin->W1 + W1->end
        parts = C1->M1
        workstation = C1->begin
    }
} for 3 Workstation, 3 Worker, 2 Product expect 1

run PositiveSingleLine4Stations {
    some disj H1, H2, H3, H4 : Human | some disj M1 : Material | some disj C1 : Component | some disj W1, W2 : Workstation - (begin + end) {
        Workstation = begin + end + W1 + W2
        Worker = Human + Robot
        Human = H1 + H2 + H3 + H4
        Robot = none
        Material = M1
        Component = C1
        Product = M1 + C1
        Dangerous = none
        // One human per workstation
        workers = begin->H1 + W1->H2 + W2->H3 + end->H4
        // Single chain: begin -> W1 -> W2 -> end
        succ = begin->W1 + W1->W2 + W2->end
        parts = C1->M1
        workstation = C1->W2
    }
} for 4 Workstation, 4 Worker, 2 Product expect 1

